import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { 
  Globe, ShieldAlert, FileSearch, Lock, Server, 
  Terminal, Play, Download, RotateCcw, CheckCircle, 
  AlertTriangle, Activity, Shield, Cpu
} from 'lucide-react';

export default function DashboardPage() {
  const location = useLocation();
  const navigate = useNavigate();

  // Retrieve default module passed from Navbar or LandingPage click
  const initialModule = location.state?.defaultModule && location.state.defaultModule !== 'all' 
    ? location.state.defaultModule 
    : 'host_info';

  const [user, setUser] = useState(null);
  const [activeModule, setActiveModule] = useState(initialModule);
  const [target, setTarget] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [terminalLogs, setTerminalLogs] = useState([]);
  const [scanResult, setScanResult] = useState(null);
  const [errorMsg, setErrorMsg] = useState('');

  // Enforce strict authentication check on page load
  useEffect(() => {
    const storedUser = localStorage.getItem('netsentinel_user');
    if (!storedUser) {
      navigate('/login', { 
        state: { message: 'Access Denied: Analyst authentication required to access the SOC Console.' } 
      });
    } else {
      setUser(JSON.parse(storedUser));
    }
  }, [navigate]);

  // Update active module if user navigates with a new state
  useEffect(() => {
    if (location.state?.defaultModule && location.state.defaultModule !== 'all') {
      setActiveModule(location.state.defaultModule);
      setScanResult(null);
      setTerminalLogs([]);
    }
  }, [location.state]);

  const modules = [
    { id: 'host_info', label: 'HOST & IP INTEL', icon: Globe, color: 'var(--accent-cyan)', placeholder: 'e.g., scanme.nmap.org or 8.8.8.8' },
    { id: 'port_threat', label: 'PORT & CVE SCAN', icon: ShieldAlert, color: 'var(--alert-red)', placeholder: 'e.g., 45.33.32.156 or example.com' },
    { id: 'subdomain_dns', label: 'SUBDOMAINS & DNS', icon: FileSearch, color: 'var(--warning-amber)', placeholder: 'e.g., tesla.com or github.com' },
    { id: 'dir_exposure', label: 'DIR EXPOSURE', icon: Lock, color: 'var(--accent-green)', placeholder: 'e.g., https://example.com' },
    { id: 'ssl_audit', label: 'SSL & HEADERS', icon: Server, color: 'var(--accent-cyan)', placeholder: 'e.g., https://google.com' }
  ];

  const currentModuleObj = modules.find(m => m.id === activeModule) || modules[0];

  // Clean domain helper
  const extractHostname = (input) => {
    return input.replace(/^https?:\/\//, '').split('/')[0].trim();
  };

  // Simulated + Live Telemetry Execution Engine
  const handleExecuteScan = async (e) => {
    e.preventDefault();
    if (!target.trim()) {
      setErrorMsg('Target parameter missing. Please enter a valid domain or IPv4 address.');
      return;
    }

    setErrorMsg('');
    setIsScanning(true);
    setScanResult(null);
    setScanProgress(10);

    const cleanTarget = extractHostname(target);
    const addLog = (msg) => {
      const time = new Date().toLocaleTimeString();
      setTerminalLogs(prev => [...prev, `[${time}] ${msg}`]);
    };

    setTerminalLogs([`[INIT] Initializing ${currentModuleObj.label} module against target: ${cleanTarget}...`]);

    // Step-by-step tactical simulation sequence
    setTimeout(() => { setScanProgress(35); addLog(`Resolving DNS records and routing packets via SOC gateway...`); }, 500);
    setTimeout(() => { setScanProgress(65); addLog(`Querying external threat intelligence endpoints...`); }, 1100);
    setTimeout(() => { setScanProgress(85); addLog(`Parsing telemetry payload & evaluating risk signatures...`); }, 1700);

    setTimeout(async () => {
      try {
        let generatedData = {};

        // Live API lookup for Host Info (falls back gracefully if blocked by CORS/adblocker)
        if (activeModule === 'host_info') {
          try {
            const res = await fetch(`http://ip-api.com/json/${cleanTarget}`);
            const data = await res.json();
            if (data.status === 'success') {
              generatedData = {
                Target: cleanTarget,
                IPv4_Address: data.query,
                ISP_Organization: data.isp,
                ASN: data.as,
                Location: `${data.city}, ${data.regionName}, ${data.country}`,
                Timezone: data.timezone,
                Risk_Status: 'VERIFIED_HOST'
              };
            } else {
              throw new Error('Fallback');
            }
          } catch {
            generatedData = {
              Target: cleanTarget,
              IPv4_Address: '104.21.48.192',
              ISP_Organization: 'Cloudflare, Inc. / Edge Network',
              ASN: 'AS13335',
              Location: 'San Francisco, California, US',
              Risk_Status: 'EDGE_PROTECTED'
            };
          }
        } 
        else if (activeModule === 'port_threat') {
          generatedData = {
            Target: cleanTarget,
            Open_Ports: [22, 80, 443, 8080],
            Detected_Services: ['OpenSSH 8.9p1', 'nginx 1.24.0', 'HTTPS/TLS 1.3', 'HTTP-Proxy'],
            Flagged_CVEs: ['CVE-2023-38408 (Medium)', 'CVE-2021-41773 (Info)'],
            Threat_Score: '4.8 / 10 (MODERATE)'
          };
        } 
        else if (activeModule === 'subdomain_dns') {
          generatedData = {
            Root_Domain: cleanTarget,
            Discovered_Subdomains: [
              `api.${cleanTarget}`,
              `mail.${cleanTarget}`,
              `dev-staging.${cleanTarget}`,
              `vpn.${cleanTarget}`,
              `cdn.${cleanTarget}`
            ],
            DNS_Records: { A: '192.0.2.14', MX: `mx1.${cleanTarget}`, NS: 'ns1.cloudflare.com' },
            CT_Log_Entries: 14
          };
        } 
        else if (activeModule === 'dir_exposure') {
          generatedData = {
            Target_Root: `https://${cleanTarget}`,
            Probed_Paths: [
              { path: '/robots.txt', status: '200 OK', severity: 'INFO' },
              { path: '/sitemap.xml', status: '200 OK', severity: 'INFO' },
              { path: '/.env', status: '403 FORBIDDEN', severity: 'SECURE' },
              { path: '/.git/config', status: '404 NOT FOUND', severity: 'SECURE' },
              { path: '/admin-login', status: '200 OK (EXPOSED)', severity: 'WARNING' }
            ],
            Leak_Assessment: '1 Low-Risk Administrative Endpoint Visible'
          };
        } 
        else if (activeModule === 'ssl_audit') {
          generatedData = {
            Domain: cleanTarget,
            SSL_Certificate: 'VALID (TLS 1.3 / ECDSA)',
            Issuer: "Let's Encrypt Authority X3",
            Expires_In: '74 Days',
            Security_Headers: {
              'Strict-Transport-Security (HSTS)': 'ENABLED',
              'Content-Security-Policy (CSP)': 'MISSING (RECOMMENDED)',
              'X-Frame-Options': 'SAMEORIGIN',
              'X-Content-Type-Options': 'nosniff'
            },
            Grade: 'B+'
          };
        }

        const finalReport = {
          id: `SCAN-${Date.now().toString().slice(-6)}`,
          timestamp: new Date().toISOString(),
          analyst: user?.name || 'SecOps Analyst',
          module: currentModuleObj.label,
          target: cleanTarget,
          findings: generatedData
        };

        // Persist to local audit logs
        const existingLogs = JSON.parse(localStorage.getItem('netsentinel_logs') || '[]');
        localStorage.setItem('netsentinel_logs', JSON.stringify([finalReport, ...existingLogs]));

        setScanProgress(100);
        addLog(`[SUCCESS] Reconnaissance complete. Report ID: ${finalReport.id}`);
        setScanResult(finalReport);
        setIsScanning(false);

      } catch (err) {
        setErrorMsg('Probe execution failed. Verify target syntax and network connection.');
        setIsScanning(false);
      }
    }, 2300);
  };

  // Export JSON Report
  const handleDownloadJSON = () => {
    if (!scanResult) return;
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(scanResult, null, 2));
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute("href", dataStr);
    downloadAnchor.setAttribute("download", `${scanResult.id}_${scanResult.target}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
  };

  if (!user) return null;

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '30px 20px 80px 20px', position: 'relative', zIndex: 1 }}>
      
      {/* TOP ANALYST STATUS BAR */}
      <div className="cyber-card" style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        flexWrap: 'wrap', 
        gap: '16px',
        padding: '16px 24px',
        marginBottom: '24px',
        borderLeft: '4px solid var(--accent-cyan)'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <Shield size={24} color="var(--accent-cyan)" />
          <div>
            <h1 className="hacker-glow" style={{ fontFamily: 'var(--font-mono)', fontSize: '18px', color: 'var(--accent-cyan)', margin: 0 }}>
              NETSENTINEL // COMMAND CONSOLE
            </h1>
            <span style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--text-muted)' }}>
              OPERATOR: <strong style={{ color: 'var(--accent-green)' }}>{user.name.toUpperCase()}</strong> ({user.email})
            </span>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--accent-green)' }}>
          <Activity size={16} />
          <span>ENGINE STATUS: ONLINE</span>
        </div>
      </div>

      {/* MODULE SELECTOR TABS */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: 'repeat(auto-fit, minmax(190px, 1fr))', 
        gap: '12px', 
        marginBottom: '24px' 
      }}>
        {modules.map((mod) => {
          const IconComponent = mod.icon;
          const isActive = activeModule === mod.id;
          return (
            <button
              key={mod.id}
              onClick={() => {
                setActiveModule(mod.id);
                setScanResult(null);
                setErrorMsg('');
              }}
              className="cyber-card"
              style={{
                padding: '14px 16px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '10px',
                border: isActive ? `1px solid ${mod.color}` : '1px solid var(--border-glow)',
                backgroundColor: isActive ? 'rgba(0, 243, 255, 0.12)' : 'rgba(13, 17, 23, 0.75)',
                boxShadow: isActive ? `0 0 15px rgba(0, 243, 255, 0.2)` : 'none',
                transition: 'all 0.2s ease',
                textAlign: 'left'
              }}
            >
              <IconComponent size={20} color={mod.color} />
              <span style={{ 
                fontFamily: 'var(--font-mono)', 
                fontSize: '12px', 
                fontWeight: 'bold', 
                color: isActive ? '#ffffff' : 'var(--text-muted)' 
              }}>
                {mod.label}
              </span>
            </button>
          );
        })}
      </div>

      {/* TARGET INPUT & EXECUTION PANEL */}
      <div className="cyber-card" style={{ padding: '28px', marginBottom: '24px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '16px' }}>
          <Cpu size={20} color={currentModuleObj.color} />
          <h2 style={{ fontFamily: 'var(--font-mono)', fontSize: '16px', color: 'var(--text-main)', margin: 0 }}>
            ACTIVE MODULE: <span style={{ color: currentModuleObj.color }}>{currentModuleObj.label}</span>
          </h2>
        </div>

        <form onSubmit={handleExecuteScan} style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 300px' }}>
            <input
              type="text"
              className="cyber-input"
              placeholder={currentModuleObj.placeholder}
              value={target}
              onChange={(e) => setTarget(e.target.value)}
              disabled={isScanning}
            />
          </div>

          <button 
            type="submit" 
            className="cyber-button" 
            disabled={isScanning}
            style={{ padding: '10px 24px', minWidth: '160px' }}
          >
            {isScanning ? (
              <>PROBING TARGET...</>
            ) : (
              <><Play size={16} /> EXECUTE PROBE</>
            )}
          </button>

          {(scanResult || terminalLogs.length > 0) && (
            <button
              type="button"
              className="cyber-button"
              onClick={() => {
                setTarget('');
                setScanResult(null);
                setTerminalLogs([]);
                setErrorMsg('');
              }}
              style={{ borderColor: 'var(--text-muted)', color: 'var(--text-muted)' }}
            >
              <RotateCcw size={16} /> CLEAR
            </button>
          )}
        </form>

        {errorMsg && (
          <div className="alert-banner" style={{ marginTop: '16px', fontSize: '12px' }}>
            <AlertTriangle size={16} />
            <span>{errorMsg}</span>
          </div>
        )}

        {/* ANIMATED SCANNER PROGRESS BAR */}
        {isScanning && (
          <div style={{ marginTop: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: 'var(--font-mono)', fontSize: '11px', color: 'var(--accent-cyan)', marginBottom: '6px' }}>
              <span>EXECUTING PACKET TELEMETRY...</span>
              <span>{scanProgress}%</span>
            </div>
            <div style={{ width: '100%', height: '6px', backgroundColor: 'rgba(255,255,255,0.08)', borderRadius: '4px', overflow: 'hidden' }}>
              <div style={{ 
                width: `${scanProgress}%`, 
                height: '100%', 
                backgroundColor: 'var(--accent-cyan)', 
                boxShadow: '0 0 10px var(--accent-cyan)',
                transition: 'width 0.4s ease'
              }} />
            </div>
          </div>
        )}
      </div>

      {/* LIVE TERMINAL OUTPUT & RESULTS SPLIT VIEW */}
      {(terminalLogs.length > 0 || scanResult) && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '24px' }}>
          
          {/* LEFT: LIVE TERMINAL CONSOLE */}
          <div className="cyber-card" style={{ padding: '20px', borderTop: '2px solid var(--accent-green)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '14px', fontFamily: 'var(--font-mono)', fontSize: '13px', color: 'var(--accent-green)' }}>
              <Terminal size={16} />
              <span>LIVE EXECUTION STREAM</span>
            </div>
            <div style={{ 
              backgroundColor: 'rgba(5, 8, 12, 0.85)', 
              padding: '14px', 
              borderRadius: '4px', 
              fontFamily: 'var(--font-mono)', 
              fontSize: '12px', 
              minHeight: '220px',
              maxHeight: '350px',
              overflowY: 'auto',
              display: 'flex',
              flexDirection: 'column',
              gap: '8px'
            }}>
              {terminalLogs.map((log, i) => (
                <div key={i} style={{ color: log.includes('[SUCCESS]') ? 'var(--accent-green)' : 'var(--text-muted)', lineHeight: '1.5' }}>
                  {log}
                </div>
              ))}
              {isScanning && <div className="hacker-cursor" style={{ color: 'var(--accent-cyan)' }}>Awaiting response</div>}
            </div>
          </div>

          {/* RIGHT: STRUCTURED INTELLIGENCE OUTPUT */}
          {scanResult && (
            <div className="cyber-card" style={{ padding: '20px', borderTop: '2px solid var(--accent-cyan)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px', flexWrap: 'wrap', gap: '10px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontFamily: 'var(--font-mono)', fontSize: '13px', color: 'var(--accent-cyan)' }}>
                  <CheckCircle size={16} color="var(--accent-green)" />
                  <span>INTELLIGENCE REPORT // {scanResult.id}</span>
                </div>

                <button onClick={handleDownloadJSON} className="cyber-button" style={{ padding: '6px 12px', fontSize: '11px' }}>
                  <Download size={13} /> EXPORT JSON
                </button>
              </div>

              <div style={{ 
                backgroundColor: 'rgba(5, 8, 12, 0.85)', 
                padding: '16px', 
                borderRadius: '4px', 
                fontFamily: 'var(--font-mono)', 
                fontSize: '12px',
                overflowX: 'auto'
              }}>
                <pre style={{ margin: 0, color: 'var(--text-main)', whiteSpace: 'pre-wrap', wordBreak: 'break-word', lineHeight: '1.6' }}>
                  {JSON.stringify(scanResult.findings, null, 2)}
                </pre>
              </div>
            </div>
          )}

        </div>
      )}

    </div>
  );
}
